RULES = json.loads('[{"when": {"flag": "escalated"}, "outcome": "escalated"}, {"when": {"recorded_by": "issue_refund"}, "outcome": "refunded"}, {"when": {"recorded_by": "rebook_flight"}, "outcome": "rebooked"}, {"when": {"recorded_by": "issue_voucher"}, "outcome": "voucher_issued"}]')
BY_HINT = json.loads('{"done": ["no_resolution", ""], "none": ["no_resolution", ""], "not_found": ["no_resolution", ""], "third_party": ["no_resolution", ""], "lookup_error": ["no_resolution", ""], "escalated": ["escalated", ""]}')
NO_REASON = json.loads('["escalated", "refunded", "rebooked", "voucher_issued", "no_resolution"]')
CLOSING = json.loads('{"lines": {"default": "Thank you for calling Freya Air. Goodbye.", "not_found": "I am sorry, I could not find the booking. You can also manage it on our website. Thank you for calling Freya Air. Goodbye.", "third_party": "Only the passenger can change the booking. Thank you for calling Freya Air. Goodbye.", "escalated": "A colleague will take it from here. Thank you for calling Freya Air. Goodbye.", "lookup_error": "I am sorry, I cannot open the booking right now because of a technical problem. Thank you for calling Freya Air. Goodbye."}, "after_records": {"prefix": "You will receive a confirmation by email.", "line": "default", "unless_flag": "escalated"} }')
HINT = 'not_found'

def match(c, L, notes, order):
    for k, v in c.items():
        if k == 'flag' and not L['flags'].get(v):
            return False
        if k == 'records' and bool(L['records']) != bool(v):
            return False
        if k == 'recorded_by' and not L['records_by'].get(v):
            return False
        if k == 'gave_up' and bool(L['gave_up']) != bool(v):
            return False
        if k == 'hint' and HINT != v:
            return False
        if k == 'notes_any' and bool(notes) != bool(v):
            return False
        if k == 'notes_all' and not (notes and all(notes[p] == v for p in order)):
            return False
    return True

