    L = ledger()
    ids = iids()
    notes = dict((n[0], n[1]) for n in L['notes'])
    order = [p for p in ids if p in notes] + [p for p in notes if p not in ids]
    out, why = BY_HINT.get(HINT, ['', ''])
    for R in RULES:
