            continue
        if 'from_note' in R:
            skip = R['from_note'].get('skip', [])
            first = [p for p in order if notes[p] not in skip][0]
            out, why = R['from_note']['map'].get(notes[first], [R.get('outcome', ''), notes[first]])
        else:
            out = R['outcome']
            rs = R.get('reason', '')
            if isinstance(rs, dict):
                val = L['flags'].get(rs['from_flag'], '')
                why = rs.get('map', dict()).get(val, val)
            else:
                why = rs
        break
    vars['close_outcome'] = out
    if why and out not in NO_REASON:
        vars['close_reason'] = why
    line = CLOSING['lines'].get(HINT, CLOSING['lines'].get('default', ''))
